function getEntriesByDotNotation(targetObj, dotPath) {
    // Split the dot-path into individual keys
    const keys = dotPath.split('.');

    // Iterate over each level of the object
    for (let i = 0; i < keys.length - 1; i++) {
        targetObj = targetObj[keys[i]]; // Get the current level of the tree
    }

    // Return the last element if there was only one level or the whole object otherwise
    return [targetObj];
}

